1	package reconcore
2	
3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"sync"
8	)
9	
10	// State is the complete database. It is small enough to live in memory and to
11	// be rewritten atomically as one JSON document after every mutation, which is
12	// what replaces a real database driver in this standard-library-only build.
13	type State struct {
14		Accounts        map[string]*Account           `json:"accounts"`
15		Journals        map[string]*Journal           `json:"journals"`
16		JournalBatches  map[string]*JournalBatch      `json:"journal_batches"`
17		Rates           []*Rate                       `json:"rates"`
18		Statements      map[string]*Statement         `json:"statements"`
19		Reconciliations map[string]*Reconciliation    `json:"reconciliations"`
20		Resolutions     map[string]*Resolution        `json:"resolutions"`
21		PeriodCloses    map[string]*PeriodClose       `json:"period_closes"`
22		Idempotency     map[string]*IdempotencyRecord `json:"idempotency"`
23	}
24	
25	func newState() *State {
26		return &State{
27			Accounts:        map[string]*Account{},
28			Journals:        map[string]*Journal{},
29			JournalBatches:  map[string]*JournalBatch{},
30			Rates:           []*Rate{},
31			Statements:      map[string]*Statement{},
32			Reconciliations: map[string]*Reconciliation{},
33			Resolutions:     map[string]*Resolution{},
34			PeriodCloses:    map[string]*PeriodClose{},
35			Idempotency:     map[string]*IdempotencyRecord{},
36		}
37	}
38	
39	// Store owns the in-memory state and its file. Every mutation runs against a
40	// copy that is persisted first, so a failed write never changes the process
41	// state and no reader ever sees a half-applied transaction.
42	type Store struct {
43		path  string
44		mutex sync.Mutex
45		state *State
46	}
47	
48	// OpenStore loads the database at path, creating it on first write.
49	func OpenStore(path string) (*Store, error) {
50		if path == "" {
51			path = "reconcore.db"
52		}
53		state := newState()
54		contents, err := os.ReadFile(path)
55		switch {
56		case err == nil:
57			if err := json.Unmarshal(contents, state); err != nil {
58				return nil, InternalError("database %s is not readable JSON: %s", path, err)
59			}
60			state.repair()
61		case os.IsNotExist(err):
62		default:
