581	// buildJournal resolves every line and freezes the balanced voucher. The
582	// caller owns the duplicate-id and closed-period policy.
583	func (s *Service) buildJournal(state *State, request *createJournalRequest, id, date, memo string) (*Journal, error) {
584		journal := &Journal{
585			ID:                 id,
586			Date:               date,
587			Memo:               memo,
588			FunctionalCurrency: s.functionalCurrency,
589			Lines:              []*JournalLine{},
590			CreatedAt:          s.now(),
591		}
592		var debits, credits int64
593		for position, raw := range request.Lines {
594			line, err := s.buildJournalLine(state, raw, position+1, date)
595			if err != nil {
596				return nil, err
597			}
598			if line.Side == "debit" {
599				debits += line.FunctionalAmountMinor
600			} else {
601				credits += line.FunctionalAmountMinor
602			}
603			journal.Lines = append(journal.Lines, line)
604		}
605		if debits != credits {
606			return nil, ValidationError(
607				"journal is not balanced in %s: debits %d, credits %d",
608				s.functionalCurrency, debits, credits,
609			)
610		}
611		journal.DebitFunctionalMinor = debits
612		journal.CreditFunctionalMinor = credits
613		return journal, nil
614	}
