638	// maxBatchJournals bounds how many vouchers one atomic batch may carry.
639	const maxBatchJournals = 100
640	
641	type createJournalBatchRequest struct {
642		ID       string                  `json:"id"`
643		Journals []*createJournalRequest `json:"journals"`
644	}
645	
646	// CreateJournalBatch imports 1 to 100 ordinary journals as one atomic unit.
647	// Every voucher is validated and constructed in request order under exactly
648	// the rules of POST /journals; any failure rejects the whole batch and writes
649	// nothing, and only a fully valid batch commits its journals, its batch record
650	// and its idempotency record in a single state write.
651	func (s *Service) CreateJournalBatch(body []byte, key string) (any, error) {
652		var request createJournalBatchRequest
653		if err := decodeObject(body, &request); err != nil {
654			return nil, err
655		}
656		id, err := validateIdentifier(request.ID, "batch id")
657		if err != nil {
658			return nil, err
659		}
660		if len(request.Journals) < 1 || len(request.Journals) > maxBatchJournals {
661			return nil, ValidationError("journals must contain between 1 and %d vouchers", maxBatchJournals)
662		}
663		type journalHead struct {
664			id   string
665			date string
666			memo string
667		}
668		heads := make([]journalHead, len(request.Journals))
669		for position, raw := range request.Journals {
670			if raw == nil {
671				return nil, ValidationError("journals[%d] must be an object", position+1)
672			}
673			journalID, date, memo, err := validateJournalHead(raw.ID, raw.Date, raw.Memo, len(raw.Lines))
674			if err != nil {
675				return nil, err
676			}
677			heads[position] = journalHead{id: journalID, date: date, memo: memo}
678		}
679		return s.runIdempotent(key, "create-journal-batch:"+id, func(state *State) (any, error) {
680			if _, found := state.JournalBatches[id]; found {
681				return nil, ConflictError("journal batch %s already exists", id)
682			}
683			seen := make(map[string]bool, len(request.Journals))
684			journals := make([]*Journal, 0, len(request.Journals))
685			journalIDs := make([]string, 0, len(request.Journals))
686			for position, raw := range request.Journals {
687				head := heads[position]
688				if seen[head.id] {
689					return nil, ConflictError("journal id %s is duplicated inside the batch", head.id)
690				}
691				seen[head.id] = true
692				if _, found := state.Journals[head.id]; found {
693					return nil, ConflictError("journal %s already exists", head.id)
694				}
695				if closedPeriodFor(state, head.date) != nil {
696					return nil, ConflictError("closed period rejects journal")
697				}
698				journal, err := s.buildJournal(state, raw, head.id, head.date, head.memo)
699				if err != nil {
700					return nil, err
701				}
702				journals = append(journals, journal)
703				journalIDs = append(journalIDs, head.id)
704			}
705			for _, journal := range journals {
706				state.Journals[journal.ID] = journal
707			}
708			batch := &JournalBatch{
709				ID:           id,
710				JournalCount: len(journalIDs),
711				JournalIDs:   journalIDs,
712				CreatedAt:    s.now(),
713			}
714			state.JournalBatches[id] = batch
715			return batch, nil
716		})
717	}
