737	// CreateReversal posts exactly one reversal journal for the journal named in
738	// the path. The reversal mirrors every line of the original with debit and
739	// credit swapped, keeps the stored amounts, rate fractions, rate sources and
740	// functional amounts, and never resolves a fresh rate, so the pair cancels
741	// exactly in both the original and the functional currency. The reversal
742	// journal itself is the durable record that the original has been reversed:
743	// both are committed in the same atomic state write, so a restart cannot
744	// allow a second reversal.
745	func (s *Service) CreateReversal(journalID string, body []byte, key string) (any, error) {
746		var request createReversalRequest
747		if err := decodeObject(body, &request); err != nil {
748			return nil, err
749		}
750		id, err := validateIdentifier(request.ID, "journal id")
751		if err != nil {
752			return nil, err
753		}
754		date, err := validateDate(request.Date, "date")
755		if err != nil {
756			return nil, err
757		}
758		memo, err := validateText(request.Memo, "memo")
759		if err != nil {
760			return nil, err
761		}
762		if memo == "" {
763			return nil, ValidationError("memo is required")
764		}
765		return s.runIdempotent(key, "create-reversal:"+journalID+":"+id, func(state *State) (any, error) {
766			original, found := state.Journals[journalID]
767			if !found {
768				return nil, NotFoundError("journal %s was not found", journalID)
769			}
770			if date < original.Date {
771				return nil, ValidationError(
772					"date must not be earlier than the date %s of journal %s",
773					original.Date, journalID,
774				)
775			}
776			if original.ReversalOf != "" {
777				return nil, ConflictError("journal %s is itself a reversal and cannot be reversed", journalID)
778			}
779			for _, journal := range state.Journals {
780				if journal.ReversalOf == journalID {
781					return nil, ConflictError("journal %s was already reversed by %s", journalID, journal.ID)
782				}
783			}
784			if _, found := state.Journals[id]; found {
785				return nil, ConflictError("journal %s already exists", id)
786			}
787			if closedPeriodFor(state, date) != nil {
788				return nil, ConflictError("closed period rejects journal")
789			}
790			reversal := &Journal{
791				ID:                    id,
792				Date:                  date,
793				Memo:                  memo,
794				FunctionalCurrency:    original.FunctionalCurrency,
795				Lines:                 make([]*JournalLine, 0, len(original.Lines)),
796				DebitFunctionalMinor:  original.CreditFunctionalMinor,
797				CreditFunctionalMinor: original.DebitFunctionalMinor,
798				CreatedAt:             s.now(),
799				ReversalOf:            journalID,
800			}
801			for _, line := range original.Lines {
802				side := "debit"
803				if line.Side == "debit" {
804					side = "credit"
805				}
806				reversal.Lines = append(reversal.Lines, &JournalLine{
807					Index:                 line.Index,
808					AccountID:             line.AccountID,
809					Side:                  side,
810					AmountMinor:           line.AmountMinor,
811					Currency:              line.Currency,
812					Rate:                  line.Rate,
813					RateNumerator:         line.RateNumerator,
814					RateDenominator:       line.RateDenominator,
815					RateSource:            line.RateSource,
816					FunctionalAmountMinor: line.FunctionalAmountMinor,
817					Reference:             line.Reference,
818				})
819			}
820			state.Journals[id] = reversal
821			return reversal, nil
822		})
823	}
