838			return nil, ValidationError("invalid period close id")
839		}
840		id := request.ID
841		start, err := validatePeriodCloseDate(request.Period.Start)
842		if err != nil {
843			return nil, err
844		}
845		end, err := validatePeriodCloseDate(request.Period.End)
846		if err != nil {
847			return nil, err
848		}
849		if !isCalendarMonth(start, end) {
