855			}
856			for _, existing := range state.PeriodCloses {
857				if existing.Period.Start[:7] == start[:7] {
858					return nil, ConflictError("calendar month is closed")
859				}
860			}
861			close := &PeriodClose{
862				ID:                   id,
863				Period:               Period{Start: start, End: end},
864				Status:               "closed",
865				ClosedAt:             s.now(),
