883	// isCalendarMonth reports whether start and end together span exactly one
884	// natural month, first day to last day.
885	func isCalendarMonth(start, end string) bool {
886		first, err := time.Parse(dateLayout, start)
887		if err != nil || first.Day() != 1 {
888			return false
889		}
890		last, err := time.Parse(dateLayout, end)
891		if err != nil {
892			return false
893		}
894		return last.Equal(first.AddDate(0, 1, -1))
895	}
