955			return nil, ValidationError("lines[%d].account_id %s does not exist", index, accountID)
956		}
957		if raw.Side != "debit" && raw.Side != "credit" {
958			return nil, ValidationError("lines[%d].side must be debit or credit", index)
959		}
960		amount, err := validateAmount(raw.AmountMinor, fmt.Sprintf("lines[%d].amount_minor", index), false, false)
961		if err != nil {
962			return nil, err
963		}
964		currency, err := validateCurrency(raw.Currency, fmt.Sprintf("lines[%d].currency", index), false)
965		if err != nil {
966			return nil, err
967		}
968		if currency == "" {
969			currency = account.Currency
970		}
971		if currency != account.Currency {
972			return nil, ValidationError(
973				"lines[%d].currency %s must match the currency %s of account %s",
974				index, currency, account.Currency, accountID,
975			)
976		}
977		reference, err := validateText(raw.Reference, fmt.Sprintf("lines[%d].reference", index))
978		if err != nil {
979			return nil, err
980		}
981		numerator, denominator, source, err := s.resolveRate(state, currency, date, raw.Rate, fmt.Sprintf("lines[%d].rate", index))
982		if err != nil {
983			return nil, err
984		}
985		functional, err := convertMinor(amount, numerator, denominator)
986		if err != nil {
987			return nil, err
988		}
989		if functional < 1 {
990			return nil, ValidationError(
991				"lines[%d] converts to zero minor units in %s; use a larger amount or a finer exchange rate",
992				index, s.functionalCurrency,
993			)
994		}
995		return &JournalLine{
996			Index:                 index,
997			AccountID:             accountID,
998			Side:                  raw.Side,
999			AmountMinor:           amount,
1000			Currency:              currency,
1001			Rate:                  raw.Rate,
1002			RateNumerator:         numerator,
1003			RateDenominator:       denominator,
1004			RateSource:            source,
1005			FunctionalAmountMinor: functional,
1006			Reference:             reference,
1007		}, nil
1008	}
