1010	// resolveRate returns the exact fraction that converts one minor unit of
1011	// currency into the functional currency for the given date.
1012	func (s *Service) resolveRate(state *State, currency, date, declared, field string) (int64, int64, string, error) {
1013		if currency == s.functionalCurrency {
1014			if declared == "" || declared == "1" {
1015				return 1, 1, "identity", nil
1016			}
1017			numerator, denominator, err := parseRateFraction(declared, field)
1018			if err != nil {
1019				return 0, 0, "", err
1020			}
1021			if numerator != denominator {
1022				return 0, 0, "", ValidationError(
1023					"%s must be omitted or exactly 1 because %s is the functional currency",
1024					field, currency,
1025				)
1026			}
1027			return 1, 1, "identity", nil
1028		}
1029		if declared != "" {
1030			numerator, denominator, err := parseRateFraction(declared, field)
1031			if err != nil {
1032				return 0, 0, "", err
1033			}
1034			return numerator, denominator, "declared", nil
1035		}
1036		if direct := latestRate(state, currency, s.functionalCurrency, date); direct != nil {
1037			return direct.Numerator, direct.Denominator, "snapshot:" + direct.Date, nil
1038		}
1039		if inverse := latestRate(state, s.functionalCurrency, currency, date); inverse != nil {
1040			return inverse.Denominator, inverse.Numerator, "snapshot-inverse:" + inverse.Date, nil
1041		}
1042		return 0, 0, "", ValidationError(
1043			"no %s/%s exchange rate snapshot exists on or before %s",
1044			currency, s.functionalCurrency, date,
1045		)
1046	}
