1071	// CreateStatement imports one bank statement.
1072	func (s *Service) CreateStatement(body []byte, key string) (any, error) {
1073		var request createStatementRequest
1074		if err := decodeObject(body, &request); err != nil {
1075			return nil, err
1076		}
1077		id, err := validateIdentifier(request.ID, "statement id")
1078		if err != nil {
1079			return nil, err
1080		}
1081		accountID, err := validateIdentifier(request.AccountID, "account_id")
1082		if err != nil {
1083			return nil, err
1084		}
1085		currency, err := validateCurrency(request.Currency, "currency", false)
1086		if err != nil {
1087			return nil, err
1088		}
1089		start, err := validateDate(request.Period.Start, "period.start")
1090		if err != nil {
1091			return nil, err
1092		}
1093		end, err := validateDate(request.Period.End, "period.end")
1094		if err != nil {
1095			return nil, err
1096		}
1097		if start > end {
1098			return nil, ValidationError("period.start must not be after period.end")
1099		}
1100		opening, err := validateAmount(request.OpeningBalanceMinor, "opening_balance_minor", true, true)
1101		if err != nil {
1102			return nil, err
1103		}
1104		closing, err := validateAmount(request.ClosingBalanceMinor, "closing_balance_minor", true, true)
1105		if err != nil {
1106			return nil, err
1107		}
1108		return s.runIdempotent(key, "create-statement:"+id, func(state *State) (any, error) {
1109			if _, found := state.Statements[id]; found {
1110				return nil, ConflictError("statement %s already exists", id)
1111			}
1112			account, found := state.Accounts[accountID]
1113			if !found {
1114				return nil, ValidationError("account_id %s does not exist", accountID)
1115			}
1116			if currency == "" {
1117				currency = account.Currency
1118			}
1119			if currency != account.Currency {
1120				return nil, ValidationError(
1121					"currency %s must match the currency %s of account %s",
1122					currency, account.Currency, accountID,
1123				)
1124			}
1125			statement := &Statement{
1126				ID:                  id,
1127				AccountID:           accountID,
1128				Currency:            currency,
1129				Period:              Period{Start: start, End: end},
1130				OpeningBalanceMinor: opening,
1131				ClosingBalanceMinor: closing,
1132				Lines:               []*StatementLine{},
1133				CreatedAt:           s.now(),
1134			}
1135			total := opening
1136			seen := map[string]bool{}
1137			for position, raw := range request.Lines {
1138				if raw == nil {
1139					return nil, ValidationError("lines[%d] must be an object", position+1)
1140				}
1141				field := fmt.Sprintf("lines[%d]", position+1)
1142				lineID, err := validateIdentifier(raw.ID, field+".id")
1143				if err != nil {
1144					return nil, err
1145				}
1146				if seen[lineID] {
1147					return nil, ValidationError("statement line id %s is duplicated", lineID)
1148				}
1149				seen[lineID] = true
1150				lineDate, err := validateDate(raw.Date, field+".date")
1151				if err != nil {
1152					return nil, err
1153				}
1154				if lineDate < start || lineDate > end {
1155					return nil, ValidationError("%s.date must fall inside the statement period", field)
1156				}
1157				amount, err := validateAmount(raw.AmountMinor, field+".amount_minor", false, true)
1158				if err != nil {
1159					return nil, err
1160				}
1161				reference, err := validateText(raw.Reference, field+".reference")
1162				if err != nil {
1163					return nil, err
1164				}
1165				description, err := validateText(raw.Description, field+".description")
1166				if err != nil {
1167					return nil, err
1168				}
1169				total += amount
1170				statement.Lines = append(statement.Lines, &StatementLine{
1171					ID:          lineID,
1172					Date:        lineDate,
1173					AmountMinor: amount,
1174					Reference:   reference,
1175					Description: description,
1176				})
1177			}
1178			if total != closing {
1179				return nil, ValidationError(
1180					"statement lines do not reconcile with the closing balance: opening %d plus lines %d is %d, not %d",
1181					opening, total-opening, total, closing,
1182				)
1183			}
1184			state.Statements[id] = statement
1185			return statement, nil
1186		})
1187	}
