1255	// CreateResolution records the immutable human disposition of one frozen
1256	// difference. The difference is addressed by its 1-based index inside the
1257	// frozen reconciliation, holds at most one resolution, and is snapshotted
1258	// into the resolution so later activity can never change what was reviewed.
1259	func (s *Service) CreateResolution(reconciliationID string, body []byte, key string) (any, error) {
1260		var request createResolutionRequest
1261		if err := decodeObject(body, &request); err != nil {
1262			return nil, err
1263		}
1264		id, err := validateIdentifier(request.ID, "resolution id")
1265		if err != nil {
1266			return nil, err
1267		}
1268		if request.DifferenceIndex < 1 {
1269			return nil, ValidationError("difference_index must be a positive integer starting at 1")
1270		}
1271		if request.Disposition != "accepted" && request.Disposition != "resolved" {
1272			return nil, ValidationError("disposition must be accepted or resolved")
1273		}
1274		reason := strings.TrimSpace(request.Reason)
1275		if reason == "" {
1276			return nil, ValidationError("reason must not be empty")
1277		}
1278		if _, err := validateText(reason, "reason"); err != nil {
1279			return nil, err
1280		}
1281		return s.runIdempotent(key, "create-resolution:"+reconciliationID+":"+id, func(state *State) (any, error) {
1282			reconciliation, found := state.Reconciliations[reconciliationID]
1283			if !found {
1284				return nil, NotFoundError("reconciliation %s was not found", reconciliationID)
1285			}
1286			if request.DifferenceIndex > len(reconciliation.Differences) {
1287				return nil, ValidationError(
1288					"difference_index %d is out of range: reconciliation %s has %d differences",
1289					request.DifferenceIndex, reconciliationID, len(reconciliation.Differences),
1290				)
1291			}
1292			if _, found := state.Resolutions[id]; found {
1293				return nil, ConflictError("resolution %s already exists", id)
1294			}
1295			for _, existing := range state.Resolutions {
1296				if existing.ReconciliationID == reconciliationID && existing.DifferenceIndex == request.DifferenceIndex {
1297					return nil, ConflictError(
1298						"difference %d of reconciliation %s already has resolution %s",
1299						request.DifferenceIndex, reconciliationID, existing.ID,
1300					)
1301				}
1302			}
1303			resolution := &Resolution{
1304				ID:               id,
1305				ReconciliationID: reconciliationID,
1306				DifferenceIndex:  request.DifferenceIndex,
1307				Disposition:      request.Disposition,
1308				Reason:           reason,
1309				Difference:       copyDifference(reconciliation.Differences[request.DifferenceIndex-1]),
1310				CreatedAt:        s.now(),
1311			}
1312			state.Resolutions[id] = resolution
1313			return resolution, nil
1314		})
1315	}
