1317	// ListResolutions reports the review progress of one reconciliation. The
1318	// counts are derived from the frozen differences, so they never change when
1319	// new journals, statements or reconciliations appear later.
1320	func (s *Service) ListResolutions(reconciliationID string) (any, error) {
1321		return s.store.View(func(state *State) (any, error) {
1322			reconciliation, found := state.Reconciliations[reconciliationID]
1323			if !found {
1324				return nil, NotFoundError("reconciliation %s was not found", reconciliationID)
1325			}
1326			records := []*Resolution{}
1327			for _, resolution := range state.Resolutions {
1328				if resolution.ReconciliationID == reconciliationID {
1329					records = append(records, resolution)
1330				}
1331			}
1332			sort.Slice(records, func(left, right int) bool {
1333				return records[left].DifferenceIndex < records[right].DifferenceIndex
1334			})
1335			differenceCount := len(reconciliation.Differences)
1336			remaining := differenceCount - len(records)
1337			status := "pending"
1338			if remaining == 0 {
1339				status = "completed"
1340			}
1341			return map[string]any{
1342				"reconciliation_id": reconciliationID,
1343				"records":           records,
1344				"difference_count":  differenceCount,
1345				"disposed_count":    len(records),
1346				"remaining_count":   remaining,
1347				"review_status":     status,
1348			}, nil
1349		})
1350	}
