1352	// ledgerEntry is one journal line seen from the ledger side of a
1353	// reconciliation. AmountMinor is signed with debits positive.
1354	type ledgerEntry struct {
1355		ID          string
1356		Date        string
1357		AmountMinor int64
1358		Reference   string
1359	}
1360	
1361	func ledgerEntries(state *State, accountID string, period Period) []*ledgerEntry {
1362		entries := []*ledgerEntry{}
1363		for _, journal := range sortedJournals(state) {
1364			if journal.Date < period.Start || journal.Date > period.End {
1365				continue
1366			}
1367			for _, line := range journal.Lines {
1368				if line.AccountID != accountID {
1369					continue
1370				}
1371				amount := line.AmountMinor
1372				if line.Side == "credit" {
1373					amount = -amount
1374				}
1375				entries = append(entries, &ledgerEntry{
1376					ID:          fmt.Sprintf("%s#%d", journal.ID, line.Index),
1377					Date:        journal.Date,
1378					AmountMinor: amount,
1379					Reference:   line.Reference,
1380				})
1381			}
1382		}
1383		return entries
1384	}
1385	
1386	var differenceOrder = map[string]int{
1387		"timing":               0,
1388		"amount_mismatch":      1,
1389		"missing_in_ledger":    2,
1390		"missing_in_statement": 3,
1391	}
1392	
1393	// computeReconciliation matches statement lines to ledger lines in three
1394	// deterministic tiers and classifies everything that stays unmatched.
1395	func (s *Service) computeReconciliation(state *State, statement *Statement, id, createdAt string) (*Reconciliation, error) {
1396		lines := make([]*StatementLine, 0, len(statement.Lines))
1397		lines = append(lines, statement.Lines...)
1398		sort.Slice(lines, func(left, right int) bool { return lines[left].ID < lines[right].ID })
1399	
1400		entries := ledgerEntries(state, statement.AccountID, statement.Period)
1401		sort.Slice(entries, func(left, right int) bool { return entries[left].ID < entries[right].ID })
1402	
1403		statementUsed := make([]bool, len(lines))
1404		ledgerUsed := make([]bool, len(entries))
1405		differences := []*Difference{}
1406		matched := 0
1407		match := func(statementIndex, ledgerIndex int, difference *Difference) {
1408			statementUsed[statementIndex] = true
1409			ledgerUsed[ledgerIndex] = true
1410			matched++
1411			if difference != nil {
1412				differences = append(differences, difference)
1413			}
1414		}
1415	
1416		// Tier 1: same signed amount and same date.
1417		for index, line := range lines {
1418			for other, entry := range entries {
1419				if ledgerUsed[other] {
1420					continue
1421				}
1422				if entry.AmountMinor == line.AmountMinor && entry.Date == line.Date {
1423					match(index, other, nil)
1424					break
1425				}
1426			}
1427		}
1428	
1429		// Tier 2: same signed amount, different date, so it only differs in timing.
1430		for index, line := range lines {
1431			if statementUsed[index] {
1432				continue
1433			}
1434			for other, entry := range entries {
1435				if ledgerUsed[other] || entry.AmountMinor != line.AmountMinor {
1436					continue
1437				}
1438				statementAmount := line.AmountMinor
1439				ledgerAmount := entry.AmountMinor
1440				match(index, other, &Difference{
1441					Type:                 "timing",
1442					Detail:               "the amounts agree but the ledger date differs from the statement date",
1443					StatementLineID:      line.ID,
1444					LedgerLineID:         entry.ID,
1445					StatementDate:        line.Date,
1446					LedgerDate:           entry.Date,
1447					StatementAmountMinor: &statementAmount,
1448					LedgerAmountMinor:    &ledgerAmount,
1449				})
1450				break
1451			}
1452		}
1453	
1454		// Tier 3: same non-empty reference but a different amount.
1455		for index, line := range lines {
1456			if statementUsed[index] || line.Reference == "" {
1457				continue
1458			}
1459			for other, entry := range entries {
1460				if ledgerUsed[other] || entry.Reference == "" || entry.Reference != line.Reference {
1461					continue
1462				}
1463				statementAmount := line.AmountMinor
1464				ledgerAmount := entry.AmountMinor
1465				match(index, other, &Difference{
1466					Type:                 "amount_mismatch",
1467					Detail:               fmt.Sprintf("reference %s appears on both sides with different amounts", line.Reference),
1468					StatementLineID:      line.ID,
1469					LedgerLineID:         entry.ID,
1470					StatementDate:        line.Date,
1471					LedgerDate:           entry.Date,
1472					StatementAmountMinor: &statementAmount,
1473					LedgerAmountMinor:    &ledgerAmount,
1474					DifferenceMinor:      statementAmount - ledgerAmount,
1475				})
1476				break
1477			}
1478		}
1479	
1480		// Everything still unmatched is missing on one side.
1481		for index, line := range lines {
1482			if statementUsed[index] {
1483				continue
1484			}
1485			amount := line.AmountMinor
1486			differences = append(differences, &Difference{
1487				Type:                 "missing_in_ledger",
1488				Detail:               "the statement line has no journal line in the period",
1489				StatementLineID:      line.ID,
1490				StatementDate:        line.Date,
1491				StatementAmountMinor: &amount,
1492				DifferenceMinor:      amount,
1493			})
1494		}
1495		for index, entry := range entries {
1496			if ledgerUsed[index] {
1497				continue
1498			}
1499			amount := entry.AmountMinor
1500			differences = append(differences, &Difference{
1501				Type:              "missing_in_statement",
1502				Detail:            "the journal line has no statement line in the period",
1503				LedgerLineID:      entry.ID,
1504				LedgerDate:        entry.Date,
1505				LedgerAmountMinor: &amount,
1506				DifferenceMinor:   -amount,
1507			})
1508		}
1509	
1510		sort.SliceStable(differences, func(left, right int) bool {
1511			a, b := differences[left], differences[right]
1512			if differenceOrder[a.Type] != differenceOrder[b.Type] {
1513				return differenceOrder[a.Type] < differenceOrder[b.Type]
1514			}
1515			if a.StatementLineID != b.StatementLineID {
1516				return a.StatementLineID < b.StatementLineID
1517			}
1518			return a.LedgerLineID < b.LedgerLineID
1519		})
1520	
1521		var ledgerNet int64
1522		for _, entry := range entries {
1523			ledgerNet += entry.AmountMinor
1524		}
1525		statementNet := statement.ClosingBalanceMinor - statement.OpeningBalanceMinor
1526	
1527		summary := DifferenceSummary{}
1528		var explained int64
1529		for _, difference := range differences {
1530			explained += difference.DifferenceMinor
1531			switch difference.Type {
1532			case "timing":
1533				summary.Timing++
1534			case "amount_mismatch":
1535				summary.AmountMismatch++
1536			case "missing_in_ledger":
1537				summary.MissingInLedger++
1538			case "missing_in_statement":
1539				summary.MissingInStatement++
1540			default:
1541				return nil, InternalError("reconciliation produced the unknown difference type %s", difference.Type)
1542			}
1543		}
1544		if 2*matched+summary.MissingInLedger+summary.MissingInStatement != len(lines)+len(entries) {
1545			return nil, InternalError("reconciliation differences are not mutually exclusive and complete")
1546		}
1547		if explained != statementNet-ledgerNet {
1548			return nil, InternalError("reconciliation differences do not add up to the period difference")
1549		}
1550	
1551		status := "balanced"
1552		if len(differences) > 0 {
1553			status = "differences_found"
1554		}
1555		return &Reconciliation{
1556			ID:                 id,
1557			StatementID:        statement.ID,
1558			AccountID:          statement.AccountID,
1559			Currency:           statement.Currency,
1560			FunctionalCurrency: s.functionalCurrency,
1561			Period:             statement.Period,
1562			Status:             status,
1563			MatchedCount:       matched,
1564			StatementLineCount: len(lines),
1565			LedgerLineCount:    len(entries),
1566			StatementNetMinor:  statementNet,
1567			LedgerNetMinor:     ledgerNet,
1568			DifferenceMinor:    statementNet - ledgerNet,
1569			Summary:            summary,
1570			Differences:        differences,
1571			CreatedAt:          createdAt,
1572		}, nil
1573	}
1574	
1575	func sortedAccounts(state *State) []*Account {
1576		accounts := make([]*Account, 0, len(state.Accounts))
1577		for _, account := range state.Accounts {
1578			accounts = append(accounts, account)
1579		}
1580		sort.Slice(accounts, func(left, right int) bool { return accounts[left].ID < accounts[right].ID })
1581		return accounts
1582	}
1583	
1584	func sortedJournals(state *State) []*Journal {
1585		journals := make([]*Journal, 0, len(state.Journals))
1586		for _, journal := range state.Journals {
1587			journals = append(journals, journal)
1588		}
1589		sort.Slice(journals, func(left, right int) bool {
1590			if journals[left].Date != journals[right].Date {
1591				return journals[left].Date < journals[right].Date
1592			}
1593			return journals[left].ID < journals[right].ID
1594		})
1595		return journals
1596	}
1597	
1598	func sortedRates(state *State) []*Rate {
1599		rates := make([]*Rate, 0, len(state.Rates))
1600		rates = append(rates, state.Rates...)
1601		sort.Slice(rates, func(left, right int) bool {
1602			a, b := rates[left], rates[right]
1603			if a.Base != b.Base {
1604				return a.Base < b.Base
1605			}
1606			if a.Quote != b.Quote {
1607				return a.Quote < b.Quote
1608			}
1609			return a.Date < b.Date
1610		})
1611		return rates
1612	}
1613	
1614	func accountTree(state *State) (map[string]*AccountNode, []*AccountNode) {
1615		nodes := map[string]*AccountNode{}
1616		for _, account := range state.Accounts {
1617			nodes[account.ID] = &AccountNode{Account: *account, Children: []*AccountNode{}}
1618		}
1619		roots := []*AccountNode{}
1620		for _, account := range sortedAccounts(state) {
1621			node := nodes[account.ID]
1622			if account.ParentID == nil {
1623				roots = append(roots, node)
1624				continue
1625			}
1626			parent, found := nodes[*account.ParentID]
1627			if !found {
1628				roots = append(roots, node)
1629				continue
1630			}
1631			parent.Children = append(parent.Children, node)
1632		}
1633		return nodes, roots
1634	}
1635	
1636	// latestRate returns the most recent snapshot for one direction that is
1637	// effective on the given date.
1638	func latestRate(state *State, base, quote, asOf string) *Rate {
1639		var best *Rate
1640		for _, rate := range state.Rates {
1641			if rate.Base != base || rate.Quote != quote || rate.Date > asOf {
1642				continue
1643			}
1644			if best == nil || rate.Date > best.Date {
1645				best = rate
1646			}
1647		}
1648		return best
1649	}
