214	func readJSONBody(request *http.Request) ([]byte, error) {
215		contentType := request.Header.Get("Content-Type")
216		mediaType, _, _ := strings.Cut(contentType, ";")
217		if strings.TrimSpace(strings.ToLower(mediaType)) != "application/json" {
218			return nil, ValidationError("Content-Type must be application/json")
219		}
220		body, err := io.ReadAll(io.LimitReader(request.Body, maxBodyBytes+1))
221		if err != nil {
222			return nil, ValidationError("request body could not be read")
223		}
224		if len(body) > maxBodyBytes {
225			return nil, ValidationError("request body must be at most %d bytes", maxBodyBytes)
226		}
227		return body, nil
228	}
229	
230	func splitPath(path string) []string {
231		parts := []string{}
232		for _, part := range strings.Split(path, "/") {
233			if part != "" {
234				parts = append(parts, part)
235			}
236		}
237		return parts
238	}
239	
240	// requireQuery rejects every query parameter that the route does not document.
241	func requireQuery(request *http.Request, allowed ...string) error {
242		names := make([]string, 0, len(request.URL.Query()))
243		for name := range request.URL.Query() {
244			names = append(names, name)
245		}
246		sort.Strings(names)
247		for _, name := range names {
248			known := false
249			for _, candidate := range allowed {
250				if name == candidate {
251					known = true
252					break
253				}
254			}
255			if !known {
256				return ValidationError("unknown query parameter %s", name)
257			}
258		}
259		return nil
260	}
261	
262	// requireSingleQuery rejects unknown query parameters and repeated values for
263	// the single documented parameter, so its value can be trusted as a scalar.
264	func requireSingleQuery(request *http.Request, name string) error {
265		query := request.URL.Query()
266		if len(query[name]) > 1 {
267			return ValidationError("query parameter %s must appear exactly once", name)
268		}
269		for candidate := range query {
270			if candidate != name {
271				return ValidationError("unknown query parameter %s", candidate)
272			}
273		}
274		return nil
275	}
276	
277	// requireNamedQueries rejects unknown query parameters and repeated values for
278	// every documented name, checking the names in the order the route documents
279	// so the first failure is reported in that order.
280	func requireNamedQueries(request *http.Request, names ...string) error {
281		query := request.URL.Query()
282		for _, name := range names {
283			if len(query[name]) == 0 {
284				return ValidationError("%s query parameter is required", name)
285			}
286			if len(query[name]) > 1 {
287				return ValidationError("query parameter %s must appear exactly once", name)
288			}
289		}
290		for candidate := range query {
291			known := false
292			for _, name := range names {
293				if candidate == name {
294					known = true
295					break
296				}
297			}
298			if !known {
299				return ValidationError("unknown query parameter %s", candidate)
300			}
301		}
302		return nil
303	}
304	
305	func writeError(writer http.ResponseWriter, err error) {
306		apiError := &Error{Code: "internal_error", Status: 500, Message: "internal server error"}
307		var typed *Error
308		if errors.As(err, &typed) {
309			apiError = typed
310		}
311		writeJSON(writer, apiError.Status, map[string]any{
312			"error": map[string]any{"code": apiError.Code, "message": apiError.Message},
313		})
314	}
315	
316	func writeJSON(writer http.ResponseWriter, status int, value any) {
317		encoded, err := json.Marshal(value)
318		if err != nil {
319			status = http.StatusInternalServerError
320			encoded = []byte(`{"error":{"code":"internal_error","message":"internal server error"}}`)
321		}
322		writer.Header().Set("Content-Type", "application/json; charset=utf-8")
323		writer.Header().Set("Content-Length", strconv.Itoa(len(encoded)))
324		writer.WriteHeader(status)
325		writer.Write(encoded)
326	}
