1745			t.Fatalf("resolution snapshot is %v", resolved["difference"])
1746		}
1747		if text(t, snapshot, "type") != "missing_in_statement" || text(t, snapshot, "ledger_line_id") != "jv-2#1" {
1748			t.Fatalf("snapshot is %v", snapshot)
1749		}
