1797	func TestResolutionIdempotencyAndConflicts(t *testing.T) {
1798		client := newClient(t)
1799		setupResolvableReconciliation(t, client)
1800	
1801		body := resolutionBody("res-1", 1, "accepted", "confirmed")
1802		firstStatus, firstRaw, _ := client.send(request{
1803			method: http.MethodPost, path: "/reconciliations/rec-1/resolutions", key: "res-replay", body: body})
1804		secondStatus, secondRaw, _ := client.send(request{
1805			method: http.MethodPost, path: "/reconciliations/rec-1/resolutions", key: "res-replay", body: body})
1806		if firstStatus != http.StatusCreated || secondStatus != http.StatusCreated {
1807			t.Fatalf("idempotent statuses are %d and %d", firstStatus, secondStatus)
1808		}
1809		if firstRaw != secondRaw {
1810			t.Fatalf("replayed response %s differs from %s", secondRaw, firstRaw)
1811		}
1812		progress := client.ok("/reconciliations/rec-1/resolutions")
1813		if integer(t, progress, "disposed_count") != 1 {
1814			t.Fatalf("replay created a second resolution: %v", progress)
1815		}
1816	
1817		// The same key used for another operation conflicts.
1818		sharedStatus, sharedRaw, _ := client.send(request{method: http.MethodPost, path: "/accounts", key: "shared",
1819			body: accountBody("9999", "Other", "asset", "CNY")})
1820		if sharedStatus != http.StatusCreated {
1821			t.Fatalf("shared-key account returned %d: %s", sharedStatus, sharedRaw)
1822		}
1823		client.expect(request{method: http.MethodPost, path: "/reconciliations/rec-1/resolutions", key: "shared",
1824			body: resolutionBody("res-9", 2, "accepted", "reuse")}, 409, "conflict", "already used for another operation")
1825	
1826		// A reused resolution id conflicts, as does a second disposition of the
1827		// same difference, and neither writes anything.
1828		client.expect(request{method: http.MethodPost, path: "/reconciliations/rec-1/resolutions", key: "dup-id",
1829			body: resolutionBody("res-1", 2, "resolved", "different difference")}, 409, "conflict", "already exists")
1830		client.expect(request{method: http.MethodPost, path: "/reconciliations/rec-1/resolutions", key: "dup-diff",
1831			body: resolutionBody("res-2", 1, "resolved", "second opinion")}, 409, "conflict", "already has resolution")
1832		progress = client.ok("/reconciliations/rec-1/resolutions")
1833		if integer(t, progress, "disposed_count") != 1 || len(objects(t, progress, "records")) != 1 {
1834			t.Fatalf("conflicts wrote records: %v", progress)
1835		}
1836	}
