1	package reconcore
2	
3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"sync"
8	)
9	
10	// State is the complete database. It is small enough to live in memory and to
11	// be rewritten atomically as one JSON document after every mutation, which is
12	// what replaces a real database driver in this standard-library-only build.
13	type State struct {
14		Accounts              map[string]*Account              `json:"accounts"`
15		Journals              map[string]*Journal              `json:"journals"`
16		JournalBatches        map[string]*JournalBatch         `json:"journal_batches"`
17		Rates                 []*Rate                          `json:"rates"`
18		Statements            map[string]*Statement            `json:"statements"`
19		Reconciliations       map[string]*Reconciliation       `json:"reconciliations"`
20		Resolutions           map[string]*Resolution           `json:"resolutions"`
21		ReconciliationReports map[string]*ReconciliationReport `json:"reconciliation_reports"`
22		PeriodCloses          map[string]*PeriodClose          `json:"period_closes"`
23		Idempotency           map[string]*IdempotencyRecord    `json:"idempotency"`
24	}
25	
26	func newState() *State {
27		return &State{
28			Accounts:              map[string]*Account{},
29			Journals:              map[string]*Journal{},
30			JournalBatches:        map[string]*JournalBatch{},
31			Rates:                 []*Rate{},
32			Statements:            map[string]*Statement{},
33			Reconciliations:       map[string]*Reconciliation{},
34			Resolutions:           map[string]*Resolution{},
35			ReconciliationReports: map[string]*ReconciliationReport{},
36			PeriodCloses:          map[string]*PeriodClose{},
37			Idempotency:           map[string]*IdempotencyRecord{},
38		}
39	}
40	
41	// Store owns the in-memory state and its file. Every mutation runs against a
42	// copy that is persisted first, so a failed write never changes the process
43	// state and no reader ever sees a half-applied transaction.
44	type Store struct {
45		path  string
46		mutex sync.Mutex
47		state *State
48	}
49	
50	// OpenStore loads the database at path, creating it on first write.
51	func OpenStore(path string) (*Store, error) {
52		if path == "" {
53			path = "reconcore.db"
54		}
55		state := newState()
56		contents, err := os.ReadFile(path)
57		switch {
58		case err == nil:
59			if err := json.Unmarshal(contents, state); err != nil {
60				return nil, InternalError("database %s is not readable JSON: %s", path, err)
61			}
62			state.repair()
63		case os.IsNotExist(err):
64		default:
65			return nil, InternalError("database %s could not be read: %s", path, err)
66		}
67		return &Store{path: path, state: state}, nil
68	}
69	
70	func (s *State) repair() {
71		if s.Accounts == nil {
72			s.Accounts = map[string]*Account{}
73		}
74		if s.Journals == nil {
75			s.Journals = map[string]*Journal{}
76		}
77		if s.JournalBatches == nil {
78			s.JournalBatches = map[string]*JournalBatch{}
79		}
80		if s.Rates == nil {
81			s.Rates = []*Rate{}
82		}
83		if s.Statements == nil {
84			s.Statements = map[string]*Statement{}
85		}
86		if s.Reconciliations == nil {
87			s.Reconciliations = map[string]*Reconciliation{}
88		}
89		if s.Resolutions == nil {
90			s.Resolutions = map[string]*Resolution{}
91		}
92		if s.ReconciliationReports == nil {
93			s.ReconciliationReports = map[string]*ReconciliationReport{}
94		}
95		if s.PeriodCloses == nil {
96			s.PeriodCloses = map[string]*PeriodClose{}
97		}
98		if s.Idempotency == nil {
99			s.Idempotency = map[string]*IdempotencyRecord{}
100		}
101	}
102	
103	// Update runs mutate against a copy of the state and commits it on success.
104	func (s *Store) Update(mutate func(state *State) error) error {
105		s.mutex.Lock()
106		defer s.mutex.Unlock()
107		clone, err := cloneState(s.state)
108		if err != nil {
109			return err
110		}
111		if err := mutate(clone); err != nil {
112			return err
113		}
114		if err := writeState(s.path, clone); err != nil {
115			return err
116		}
117		s.state = clone
118		return nil
119	}
120	
121	// View runs read against the committed state under the store lock.
122	func (s *Store) View(read func(state *State) (any, error)) (any, error) {
123		s.mutex.Lock()
124		defer s.mutex.Unlock()
125		return read(s.state)
126	}
127	
128	func cloneState(state *State) (*State, error) {
129		encoded, err := json.Marshal(state)
130		if err != nil {
131			return nil, InternalError("database could not be serialised: %s", err)
132		}
133		clone := newState()
134		if err := json.Unmarshal(encoded, clone); err != nil {
135			return nil, InternalError("database could not be restored: %s", err)
136		}
137		return clone, nil
138	}
139	
140	func writeState(path string, state *State) error {
141		encoded, err := json.MarshalIndent(state, "", "  ")
142		if err != nil {
143			return InternalError("database could not be serialised: %s", err)
144		}
145		encoded = append(encoded, '\n')
146		if directory := filepath.Dir(path); directory != "" && directory != "." {
147			if err := os.MkdirAll(directory, 0o755); err != nil {
148				return InternalError("database directory could not be created: %s", err)
149			}
150		}
151		temporary := path + ".tmp"
152		if err := os.WriteFile(temporary, encoded, 0o644); err != nil {
153			return InternalError("database could not be written: %s", err)
154		}
155		if err := os.Rename(temporary, path); err != nil {
156			return InternalError("database could not be committed: %s", err)
157		}
158		return nil
159	}

